// PCM monitor transmitter for the Tang Mega 138K CH569 HSPI bridge.
//
// Audio samples are produced in the slow audio clock domain and cross into the
// HSPI clock domain through the Gowin-generated pcm_sample_async_fifo IP. The
// HSPI side groups seven PC-visible PCM frames into one 4096-byte HSPI payload:
//
//   7 * (14-byte header + 64 stereo pairs * 8 bytes) + 414 zeros =4096B
// Each signed32 channel carries all24 PCM bits left-aligned (low8bits zero).
//
// The actual CH569-side HSPI packet header and CRC are generated by EXM_HSPI,
// matching the official ch569_hspi2cdc FPGA example.
module pcm_hspi_monitor_tx #(
    parameter ENABLE_DIAGNOSTICS = 1'b0,
    parameter integer SAMPLE_RATE_HZ = 96008
)(
    input        audio_clk_i,
    input        hspi_clk_i,
    input        audio_rst_n_i,
    input        hspi_rst_n_i,

    input        sample_valid_i,
    input [23:0] sample_left_i,
    input [23:0] sample_right_i,

    output       hspi_clk_o,
    output       hspi_req_o,
    input        hspi_ready_i,
    output       hspi_valid_o,
    output [15:0] hspi_data_o,
    output       hspi_data_oe_o,

    output [15:0] frames_sent_o,
    output [15:0] samples_dropped_o,
    output        hspi_ready_sync_o,
    output        sending_o,
    output [21:0] diag_o
);

localparam [12:0] BLOCK_WORD_COUNT = 13'd1792;
localparam [15:0] FRAMES_PER_BLOCK_COUNT = 16'd7;

localparam [15:0] FRAME_MAGIC      = 16'hA55A;
localparam [15:0] FRAME_VER_FLAGS  = 16'h0301; // v1, stereo | signed32 containers
localparam [31:0] SAMPLE_RATE_WORD = SAMPLE_RATE_HZ;
localparam [15:0] SAMPLE_RATE_LO   = SAMPLE_RATE_WORD[15:0];
localparam [15:0] SAMPLE_RATE_HI   = SAMPLE_RATE_WORD[31:16];
localparam [15:0] PAYLOAD_BYTES    = 16'd512;

localparam [8:0]  WORDS_PER_FRAME  = 9'd263;
localparam [10:0] PCM_BLOCK_WORDS  = 11'd1841;
localparam [11:0] HSPI_TX_LEN      = 12'd4095; // bytes minus one

localparam [1:0] ST_WAIT      = 2'd0;
localparam [1:0] ST_START     = 2'd1;
localparam [1:0] ST_SEND      = 2'd2;
localparam [1:0] ST_GAP       = 2'd3;

wire        fifo_full_w;
wire        fifo_empty_w;
wire [15:0] fifo_q_w;
wire        fifo_wr_en_w;
wire        fifo_rd_en_w;
wire [12:0] fifo_read_count_w;

reg  [1:0]  state_r;
reg  [15:0] block_seq_r;
reg  [15:0] next_seq_r;
reg  [15:0] frames_sent_r;
reg  [15:0] samples_dropped_r;
reg         tx_act_r;
reg  [7:0]  gap_count_r;
reg         hspi_ready_meta_r;
reg         hspi_ready_sync_r;

wire        hspi_tx_clk_w;
wire        hspi_tx_req_w;
wire        hspi_tx_vld_w;
wire [31:0] hspi_tx_data_w;
wire [2:0]  hspi_tx_oe_w;
wire        hspi_tx_done_w;
wire [8:0]  hspi_tx_addr_w;
wire [10:0] hspi_tx_word_addr_w;
wire [31:0] hspi_ram_rdata_w;
wire        unused_hspi_ack_w;
wire        unused_rx_done_w;
wire        unused_rx_crc_error_w;
wire        unused_rx_num_error_w;
wire [15:0] unused_rx_crc_value_w;
wire        unused_rx_write_w;
wire [8:0]  unused_rx_addr_w;
wire [31:0] unused_rx_data_w;
wire        unused_ram_clk_w;
wire        unused_ram_csn_w;
wire        unused_ram_wen_w;
wire [8:0]  unused_ram_addr_w;
wire [31:0] unused_ram_wdata_w;

// One coherent24-bit stereo pair becomes four16-bit FIFO writes.
// Both channels are left-aligned in signed32 (low8bits zero), preserving
// every source bit and the original FIFO/512B payload/4096B block layout.
// If full, retain the unfinished pair; discard only complete new pairs.
// This prevents a full FIFO from shifting channel/word alignment.
reg [63:0] pending_pair_r;
reg [1:0] pending_word_r;
reg pending_valid_r;
wire pair_slot_ready_w = !pending_valid_r || (fifo_wr_en_w && pending_word_r==2'd3);
assign fifo_wr_en_w = pending_valid_r & ~fifo_full_w;
always @(posedge audio_clk_i or negedge audio_rst_n_i)begin
    if(!audio_rst_n_i)begin
        pending_pair_r<=0;pending_word_r<=0;pending_valid_r<=0;
    end else begin
        if(fifo_wr_en_w)begin
            pending_pair_r<=pending_pair_r>>16;
            pending_word_r<=pending_word_r+1'b1;
            if(pending_word_r==2'd3)pending_valid_r<=0;
        end
        if(sample_valid_i && pair_slot_ready_w)begin
            pending_pair_r<={sample_right_i,8'd0,sample_left_i,8'd0};
            pending_word_r<=0;pending_valid_r<=1;
        end
    end
end

assign hspi_clk_o = hspi_tx_clk_w;
assign hspi_req_o = hspi_tx_req_w;
assign hspi_valid_o = hspi_tx_vld_w;
assign hspi_data_o = hspi_tx_data_w[15:0];
assign hspi_data_oe_o = hspi_tx_oe_w[1];
assign frames_sent_o = frames_sent_r;
assign samples_dropped_o = samples_dropped_r;
assign hspi_ready_sync_o = hspi_ready_sync_r;
assign sending_o = (state_r == ST_SEND) | hspi_tx_req_w;
// Observation only: no diagnostic bit feeds packet, FIFO, reset or audio logic.
// [21:6] completed PCM frames (seven per HSPI packet, wraps at16bits).
// [5:0] audio-reset-released, sample-seen-since-audio-reset, FIFO-full,
//       whole-block-ready, synchronized CH569-ready, sending/waiting-ready.
generate if(ENABLE_DIAGNOSTICS) begin:g_diagnostics
reg diag_sample_seen_r;
(* syn_preserve = 1, ASYNC_REG = "TRUE" *) reg [2:0] diag_audio_meta_r;
(* syn_preserve = 1, ASYNC_REG = "TRUE" *) reg [2:0] diag_audio_sync_r;
always @(posedge audio_clk_i or negedge audio_rst_n_i)begin
    if(!audio_rst_n_i)diag_sample_seen_r<=1'b0;
    else if(sample_valid_i)diag_sample_seen_r<=1'b1;
end
always @(posedge hspi_clk_i or negedge hspi_rst_n_i)begin
    if(!hspi_rst_n_i)begin diag_audio_meta_r<=0;diag_audio_sync_r<=0;end
    else begin
        diag_audio_meta_r<={audio_rst_n_i,diag_sample_seen_r,fifo_full_w};
        diag_audio_sync_r<=diag_audio_meta_r;
    end
end
assign diag_o={frames_sent_r,diag_audio_sync_r,
               (!fifo_empty_w && fifo_read_count_w>=BLOCK_WORD_COUNT),
               hspi_ready_sync_r,sending_o};
end else begin:g_no_diagnostics
    assign diag_o=22'd0;
end endgenerate
// The generated standard FIFO has no extra output register: one read-clock
// edge makes the next word available. EXM captures the current payload and
// increments its word address on that same edge. Read one word ahead only
// when the following address is PCM; do not pop during headers or padding.
wire [16:0] current_word_w = tx_info_for_addr(hspi_tx_word_addr_w, fifo_q_w);
wire [10:0] next_word_addr_w = hspi_tx_word_addr_w + 11'd1;
wire [16:0] next_word_w = tx_info_for_addr(next_word_addr_w, 16'd0);
assign fifo_rd_en_w = state_r == ST_SEND && next_word_w[16] && !fifo_empty_w;
assign hspi_ram_rdata_w = {16'h0000, current_word_w[15:0]};

pcm_sample_async_fifo u_pcm_sample_async_fifo(
    .Data(pending_pair_r[15:0]),
    .Reset(~audio_rst_n_i | ~hspi_rst_n_i),
    .WrClk(audio_clk_i),
    .RdClk(hspi_clk_i),
    .WrEn(fifo_wr_en_w),
    .RdEn(fifo_rd_en_w),
    .Rnum(fifo_read_count_w),
    .Q(fifo_q_w),
    .Empty(fifo_empty_w),
    .Full(fifo_full_w)
);

always @(posedge audio_clk_i or negedge audio_rst_n_i) begin
    if (!audio_rst_n_i) begin
        samples_dropped_r <= 16'd0;
    end else if (sample_valid_i && !pair_slot_ready_w) begin
        samples_dropped_r <= samples_dropped_r + 1'b1;
    end
end

always @(posedge hspi_clk_i or negedge hspi_rst_n_i) begin
    if (!hspi_rst_n_i) begin
        hspi_ready_meta_r <= 1'b0;
        hspi_ready_sync_r <= 1'b0;
    end else begin
        hspi_ready_meta_r <= hspi_ready_i;
        hspi_ready_sync_r <= hspi_ready_meta_r;
    end
end

always @(posedge hspi_clk_i or negedge hspi_rst_n_i) begin
    if (!hspi_rst_n_i) begin
        state_r       <= ST_WAIT;
        block_seq_r   <= 16'd0;
        next_seq_r    <= 16'd0;
        frames_sent_r <= 16'd0;
        tx_act_r      <= 1'b0;
        gap_count_r   <= 8'd0;
    end else begin
        tx_act_r     <= 1'b0;

        case (state_r)
            ST_WAIT: begin
                // Rnum is generated in the read clock domain. Reserve a whole
                // block before starting the non-stallable native HSPI burst.
                if (!fifo_empty_w && fifo_read_count_w >= BLOCK_WORD_COUNT) begin
                    block_seq_r <= next_seq_r;
                    state_r <= ST_START;
                end
            end

            ST_START: begin
                tx_act_r <= 1'b1;
                state_r <= ST_SEND;
            end

            ST_SEND: begin
                if (hspi_tx_done_w) begin
                    next_seq_r <= next_seq_r + FRAMES_PER_BLOCK_COUNT;
                    frames_sent_r <= frames_sent_r + FRAMES_PER_BLOCK_COUNT;
                    gap_count_r <= 8'd0;
                    state_r <= ST_GAP;
                end
            end

            ST_GAP: begin
                gap_count_r <= gap_count_r + 1'b1;
                if (gap_count_r == 8'd63)
                    state_r <= ST_WAIT;
            end

            default: state_r <= ST_WAIT;
        endcase
    end
end

// {is_pcm_word, wire_word[15:0]}; all PCM comes directly from the official FIFO.
function [16:0] tx_info_for_addr;
    input [10:0] addr_i;
    input [15:0] pcm_word_i;
    reg [2:0] frame_i;
    reg [8:0] frame_word_i;
    reg [10:0] frame_word_full_i;
    begin
        if (addr_i >= PCM_BLOCK_WORDS) begin
            tx_info_for_addr = 17'd0;
        end else begin
            if (addr_i < 11'd263) begin
                frame_i = 3'd0;
                frame_word_full_i = addr_i;
            end else if (addr_i < 11'd526) begin
                frame_i = 3'd1;
                frame_word_full_i = addr_i - 11'd263;
            end else if (addr_i < 11'd789) begin
                frame_i = 3'd2;
                frame_word_full_i = addr_i - 11'd526;
            end else if (addr_i < 11'd1052) begin
                frame_i = 3'd3;
                frame_word_full_i = addr_i - 11'd789;
            end else if (addr_i < 11'd1315) begin
                frame_i = 3'd4;
                frame_word_full_i = addr_i - 11'd1052;
            end else if (addr_i < 11'd1578) begin
                frame_i = 3'd5;
                frame_word_full_i = addr_i - 11'd1315;
            end else begin
                frame_i = 3'd6;
                frame_word_full_i = addr_i - 11'd1578;
            end
            frame_word_i = frame_word_full_i[8:0];

            case (frame_word_i)
                9'd0: tx_info_for_addr = {1'b0, FRAME_MAGIC};
                9'd1: tx_info_for_addr = {1'b0, FRAME_VER_FLAGS};
                9'd2: tx_info_for_addr = {1'b0, (block_seq_r + {13'd0, frame_i})};
                9'd3: tx_info_for_addr = {1'b0, SAMPLE_RATE_LO};
                9'd4: tx_info_for_addr = {1'b0, SAMPLE_RATE_HI};
                9'd5: tx_info_for_addr = {1'b0, PAYLOAD_BYTES};
                9'd6: tx_info_for_addr = 17'd0;
                default: tx_info_for_addr = {1'b1, pcm_word_i};
            endcase
        end
    end
endfunction

EXM_HSPI #(
    .TX_LEN(HSPI_TX_LEN),
    .HSPI_UDF(26'h000ffff),
    .TX_ADDR(9'h000),
    .RX_ADDR(9'h000)
) u_exm_hspi (
    .HTCLK(hspi_tx_clk_w),
    .HTREQ(hspi_tx_req_w),
    .HTRDY(hspi_ready_i),
    .HTVLD(hspi_tx_vld_w),
    .HTD(hspi_tx_data_w),
    .HTOE(hspi_tx_oe_w),
    .tx_act(tx_act_r),
    .tx_len(HSPI_TX_LEN),
    .HRCLK(hspi_clk_i),
    .HRACT(1'b0),
    .HRVLD(1'b0),
    .HTACK(unused_hspi_ack_w),
    .HRD(32'd0),
    .rstn(hspi_rst_n_i),
    .clk(hspi_clk_i),
    .dat_mod(2'b01),
    .ram_clk(unused_ram_clk_w),
    .ram_csn(unused_ram_csn_w),
    .ram_wen(unused_ram_wen_w),
    .ram_addr(unused_ram_addr_w),
    .ram_rdata(hspi_ram_rdata_w),
    .ram_wdata(unused_ram_wdata_w),
    .rx_write(unused_rx_write_w),
    .rx_addr(unused_rx_addr_w),
    .rx_data(unused_rx_data_w),
    .tx_addr(hspi_tx_addr_w),
    .tx_word_addr(hspi_tx_word_addr_w),
    .tx_done(hspi_tx_done_w),
    .rx_done(unused_rx_done_w),
    .rx_crc_error(unused_rx_crc_error_w),
    .rx_num_error(unused_rx_num_error_w),
    .rx_crc_value(unused_rx_crc_value_w)
);

endmodule
